/* Japan · Itinerary — offline service worker.
 * Precaches the whole site, and decrypts the private files (vault/*.bin)
 * on the device with the key saved by the unlock screen. Generated by
 * scripts/build.mjs; edit pwa/sw.js, not docs/sw.js. */
'use strict';

var VERSION = "b65975543ece";
var PRECACHE = ["assets/app-icon-180.png","assets/app-icon-32.png","assets/app-icon-512.png","assets/app-icon-720.png","fonts/inter-cyrillic-ext.woff2","fonts/inter-cyrillic.woff2","fonts/inter-greek-ext.woff2","fonts/inter-greek.woff2","fonts/inter-latin-ext.woff2","fonts/inter-latin.woff2","fonts/inter-vietnamese.woff2","fonts/inter.css","index.html","manifest.webmanifest","sky-strip-1.png","sky-strip-2.png","sky-strip-3.png","vault/03900386fb67bdfceadf9a57.bin","vault/0da466f38ca55fa94d555a8f.bin","vault/1fc454897fb339e17b9f13d2.bin","vault/2bd08e3d9258d4ca9b0f950f.bin","vault/4998c447b1d2de58b1d6fca5.bin","vault/52b7ea56e55a6a6d802da709.bin","vault/61398090bb9f98e6508e6f4d.bin","vault/662976383c86691a244a6b9c.bin","vault/7689509d2d62fa8d19b24ed6.bin","vault/83e5c06b6530b171c2010f12.bin","vault/8707a082843051ad33870775.bin","vault/99fd915ebe563e6de5b33838.bin","vault/c36f96960d565c8046a5cec5.bin","vault/d513eac09c981ded49a1c102.bin","vault/e621eba341c9b375c989a7b0.bin","vault/e78ef12c986d39cc0dafd4cc.bin","vault/index.bin","vault/meta.json","vendor/pdfjs/pdf.min.js","vendor/pdfjs/pdf.worker.min.js"];
var CACHE = 'jp-' + VERSION;
var SCOPE = new URL(self.registration.scope);
var CONCURRENCY = 4;

function broadcast(msg){
  return self.clients.matchAll({ includeUncontrolled: true, type: 'window' }).then(function(cs){
    cs.forEach(function(c){ c.postMessage(msg); });
  });
}

function isVaultBlob(rel){ return /^vault\/[0-9a-f]+\.bin$/.test(rel) && rel !== 'vault/index.bin'; }

self.addEventListener('install', function(event){
  event.waitUntil((async function(){
    var cache = await caches.open(CACHE);
    var oldNames = (await caches.keys()).filter(function(n){ return n.indexOf('jp-') === 0 && n !== CACHE; });
    var total = PRECACHE.length, done = 0, next = 0, lastPost = 0;

    async function fromOldCache(url){
      for(var i = 0; i < oldNames.length; i++){
        var c = await caches.open(oldNames[i]);
        var hit = await c.match(url);
        if(hit) return hit;
      }
      return null;
    }

    async function worker(){
      while(next < total){
        var rel = PRECACHE[next++];
        var url = new URL(rel, SCOPE).href;
        // Vault blobs are content-addressed: an unchanged file keeps its name,
        // so reuse the copy already on the phone instead of downloading it again.
        var res = isVaultBlob(rel) ? await fromOldCache(url) : null;
        if(!res){
          res = await fetch(url, { cache: 'reload' });
          if(!res.ok) throw new Error(rel + ' → HTTP ' + res.status);
        }
        await cache.put(url, res);
        done++;
        var now = Date.now();
        if(now - lastPost > 150 || done === total){ lastPost = now; broadcast({ type: 'progress', done: done, total: total }); }
      }
    }

    try {
      var ws = [];
      for(var i = 0; i < CONCURRENCY; i++) ws.push(worker());
      await Promise.all(ws);
    } catch(err){
      await caches.delete(CACHE);
      await broadcast({ type: 'error', message: String(err && err.message || err) });
      throw err;
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', function(event){
  event.waitUntil((async function(){
    var names = await caches.keys();
    await Promise.all(names.filter(function(n){ return n.indexOf('jp-') === 0 && n !== CACHE; })
      .map(function(n){ return caches.delete(n); }));
    await self.clients.claim();
    await broadcast({ type: 'ready', version: VERSION });
  })());
});

self.addEventListener('message', function(event){
  if(event.data && event.data.type === 'status' && event.source){
    event.source.postMessage({ type: 'ready', version: VERSION });
  }
});

// ---------- key + vault ----------
function idb(){
  return new Promise(function(res, rej){
    var r = indexedDB.open('jp-vault', 1);
    r.onupgradeneeded = function(){ r.result.createObjectStore('kv'); };
    r.onsuccess = function(){ res(r.result); };
    r.onerror = function(){ rej(r.error); };
  });
}
function idbOp(mode, fn){
  return idb().then(function(db){ return new Promise(function(res, rej){
    var tx = db.transaction('kv', mode), req = fn(tx.objectStore('kv'));
    tx.oncomplete = function(){ db.close(); res(req && req.result); };
    tx.onerror = function(){ db.close(); rej(tx.error); };
  }); });
}

async function cachedBytes(rel){
  var url = new URL(rel, SCOPE).href;
  var res = await caches.match(url);
  if(!res){
    res = await fetch(url);
    if(!res.ok) throw new Error(rel + ' → HTTP ' + res.status);
  }
  return new Uint8Array(await res.arrayBuffer());
}

async function decryptWith(key, blob){
  return crypto.subtle.decrypt({ name: 'AES-GCM', iv: blob.slice(0, 12) }, key, blob.slice(12));
}

var memo = null; // { raw: string, key: CryptoKey, index: {} }

async function getVault(){
  var rec;
  try { rec = await idbOp('readonly', function(s){ return s.get('key'); }); } catch(e){ return null; }
  if(!rec || !rec.raw) return null;
  var rawId = Array.prototype.join.call(new Uint8Array(rec.raw), ',');
  if(memo && memo.raw === rawId && memo.version === VERSION) return memo;
  try {
    var key = await crypto.subtle.importKey('raw', rec.raw, 'AES-GCM', false, ['decrypt']);
    var index = JSON.parse(new TextDecoder().decode(await decryptWith(key, await cachedBytes('vault/index.bin'))));
    memo = { raw: rawId, key: key, index: index, version: VERSION };
    return memo;
  } catch(e){
    // Wrong or outdated key (the passphrase changed): forget it so the unlock screen shows.
    if(e && e.name === 'OperationError'){
      try { await idbOp('readwrite', function(s){ return s.delete('key'); }); } catch(_){}
    }
    memo = null;
    return null;
  }
}

async function vaultResponse(rel){
  var v = await getVault();
  if(!v) return null;
  var entry = v.index[rel];
  if(!entry) return null;
  var plain = await decryptWith(v.key, await cachedBytes('vault/' + entry.id + '.bin'));
  return new Response(plain, { status: 200, headers: {
    'Content-Type': entry.type,
    'Content-Length': String(plain.byteLength),
    'Cache-Control': 'no-store'
  } });
}

async function cacheFirst(request){
  var hit = await caches.match(request, { ignoreSearch: true });
  if(hit) return hit;
  return fetch(request);
}

async function loaderPage(){
  var hit = await caches.match(new URL('index.html', SCOPE).href);
  return hit || fetch(new URL('index.html', SCOPE).href);
}

async function handle(request, rel){
  if(rel === '' || rel === 'index.html'){
    if(request.mode === 'navigate'){
      try {
        var app = await vaultResponse('index.html');
        if(app) return app;
      } catch(e){}
      return loaderPage();
    }
    return cacheFirst(request);
  }
  try {
    var v = await vaultResponse(rel);
    if(v) return v;
  } catch(e){
    return new Response('This file could not be opened offline.', { status: 500, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
  }
  try {
    return await cacheFirst(request);
  } catch(e){
    if(request.mode === 'navigate') return loaderPage();
    return new Response('', { status: 504, statusText: 'Offline' });
  }
}

self.addEventListener('fetch', function(event){
  var request = event.request;
  if(request.method !== 'GET') return;
  var url = new URL(request.url);
  if(url.origin !== SCOPE.origin || url.pathname.indexOf(SCOPE.pathname) !== 0) return; // network as usual
  var rel;
  try { rel = decodeURIComponent(url.pathname.slice(SCOPE.pathname.length)); } catch(e){ return; }
  if(rel === 'sw.js') return;
  event.respondWith(handle(request, rel));
});
